/** The BaseProcess defines a common interface for all post processing steps.
 * A post processing step is run after a successful import if the caller
 * specified the corresponding flag when calling ReadFile().
 * Enum #aiPostProcessSteps defines which flags are available.
 * After a successful import the Importer iterates over its internal array
 * of processes and calls IsActive() on each process to evaluate if the step
 * should be executed. If the function returns true, the class' Execute()
 * function is called subsequently.
 */
class ASSIMP_API BaseProcess {
    friend class Importer;

public:
    /** @brief Constructor to be privately used by Importer */
    BaseProcess() AI_NO_EXCEPT;

    /** @brief Destructor */
    virtual ~BaseProcess() = default;

    // -------------------------------------------------------------------
    /**
     * @brief Returns whether the processing step is present in the given flag.
     * @param pFlags The processing flags the importer was called with. A
     *   bitwise combination of #aiPostProcessSteps.
     * @return true if the process is present in this flag fields,
     *   false if not.
     */
    virtual bool IsActive(unsigned int pFlags) const = 0;

    // -------------------------------------------------------------------
    /** Check whether this step expects its input vertex data to be
     *  in verbose format. */
    virtual bool RequireVerboseFormat() const;

    // -------------------------------------------------------------------
    /**
     * @brief Executes the post processing step on the given imported data.
     * The function deletes the scene if the post-process step fails (
     * the object pointer will be set to nullptr).
     * @param pImp Importer instance (pImp->mScene must be valid)
     */
    void ExecuteOnScene(Importer *pImp);

    // -------------------------------------------------------------------
    /**
     * @brief Called prior to ExecuteOnScene().
     * The function is a request to the process to update its configuration
     * basing on the Importer's configuration property list.
     */
    virtual void SetupProperties(const Importer *pImp);

    // -------------------------------------------------------------------
    /**
     * @brief Executes the post processing step on the given imported data.
     * A process should throw an ImportErrorException* if it fails.
     * This method must be implemented by deriving classes.
     * @param pScene The imported data to work at.
     */
    virtual void Execute(aiScene *pScene) = 0;

    // -------------------------------------------------------------------
    /** Assign a new SharedPostProcessInfo to the step. This object
     *  allows multiple post-process steps to share data.
     * @param sh May be nullptr
     */
    inline void SetSharedData(SharedPostProcessInfo *sh) {
        shared = sh;
    }

    // -------------------------------------------------------------------
    /** Get the shared data that is assigned to the step.
    */
    inline SharedPostProcessInfo *GetSharedData() {
        return shared;
    }

protected:
    /** See the doc of #SharedPostProcessInfo for more details */
    SharedPostProcessInfo *shared;

    /** Currently active progress handler */
    ProgressHandler *progress;
};

} // end of namespace Assimp

#endif // AI_BASEPROCESS_H_INC
